mapper.sql:
SELECT ranked.target_id AS target_id, ranked.reason AS reason, ranked.content AS content, ranked.created_at AS created_at FROM ( SELECT r.${targetColumn} AS target_id, r.reason AS reason, r.content AS content, r.created_at AS created_at, ROW_NUMBER() OVER (PARTITION BY r.${targetColumn} ORDER BY r.created_at DESC, r.id DESC) AS row_num FROM ${reportTable} r WHERE r.reviewed_at IS NULL
AND r.${targetColumn} IN
#{targetId}
) ranked WHERE ranked.row_num <= #{maxPerTarget} ORDER BY ranked.target_id ASC, ranked.row_num ASC
